<script setup lang="ts">
import{ref}from'vue';import{useApi,useEvents,usePolling}from'../composables/api';import{health,packages,yamVersion}from'../composables/state';import UiIcon from'../components/UiIcon.vue'
const host=location.host,api=useApi(),sensors=ref<any[]>([])
async function load(){try{health.info=await api('/api/darkls/health');health.error='';sensors.value=await api('/api/darkls/sensors')}catch(e){health.error=(e as Error).message}}usePolling(load,10000);useEvents(()=>void load(),['darkls:authchanged'])
</script>
<template><header class="page-head"><div><h1><UiIcon name="home" :size="24"/>Главная</h1><div class="sub" id="station-address">{{health.info?host:'Подключение…'}}</div></div><div class="actions"><span class="badge" id="hero-status">{{health.info?'● Панель работает на колонке':'Проверяем связь'}}</span><button class="btn" data-refresh @click="load"><UiIcon name="refresh"/>Обновить</button></div></header><div id="connection-error" class="card hint" role="status" :hidden="!health.error">{{health.error}}</div>
<section class="card"><div class="card-head"><h2><UiIcon name="box"/>YAM v2</h2><span class="badge" id="y2-home-version">{{yamVersion}}</span></div><p class="hint">Актуальный менеджер пакетов .yampkg работает прямо на колонке.</p><a class="btn primary" href="#yam"><UiIcon name="layers"/>Открыть YAM v2</a></section>
<section class="card"><div class="card-head"><h2><UiIcon name="info"/>Локальный доступ</h2><span class="status-dot" :class="health.info&&!health.error?'good':'bad'" id="adb-dot"></span></div><strong class="native-state" id="adb-state">{{health.info?'Готов':'Проверка…'}}</strong><p class="hint" id="adb-detail">{{health.info?'Панель управляет колонкой локально; ADB и yamd не требуются.':'Панель работает на колонке'}}</p><a class="btn" href="#console"><UiIcon name="term"/>Консоль</a></section>
<section class="card"><div class="card-head"><h2><UiIcon name="info"/>Управление колонкой</h2><span class="meta" id="hero-platform">{{health.info?.device?.model||'Мини 3 Про'}} · {{health.info?.device?.platform||'pickle'}}</span></div><div class="row"><a v-for="v in [['overview','grid','Открыть обзор'],['player','music','Открыть плеер'],['files','folder','Файлы'],['charts','chart','Графики'],['settings','gear','Настройки']]" :key="v[0]" class="btn" :class="{primary:v[0]==='overview'}" :href="'#'+v[0]"><UiIcon :name="v[1]"/>{{v[2]}}</a></div><p class="hint">Все разделы открываются здесь. Управление идёт локально; ПК, ADB и yamd не требуются.</p></section>
<div class="cols"><article class="card"><div class="card-head"><h2><UiIcon name="box"/>Пакеты YAM <span class="badge" id="home-count">{{packages.length}}</span></h2><a class="btn sm" href="#apps"><UiIcon name="box"/>Управлять</a></div><div id="home-packages" class="placeholder"><div v-for="p in packages.slice(0,4)" :key="p.name" class="summary-row"><a href="#apps">{{p.name}}</a><span>{{p.version}} · {{p.services?.filter((s:any)=>s.status==='running').length||0}} запущено</span></div><p v-if="!packages.length" class="hint">Приложений пока нет. <a href="#yam">Установить через YAM</a></p></div></article><article class="card"><div class="card-head"><h2><UiIcon name="info"/>Датчики</h2><span class="meta">Данные ядра · sysfs</span></div><div id="sensors"><div v-for="s in sensors" :key="s.id" class="sensor-row"><span>{{s.id}}</span><b>{{Number(s.value).toLocaleString('ru-RU',{maximumFractionDigits:1})}} {{s.unit}}</b></div><template v-if="!sensors.length">Ядро не предоставляет поддерживаемых датчиков через sysfs.</template></div><p class="hint">Только датчики, обнаруженные на колонке.</p></article></div></template>
